package com.hau.question.presentation.response;
import com.hau.question.domain.model.*; import java.time.Instant; import java.util.UUID;
public final class CatalogResponse {private CatalogResponse(){} public record SubjectView(UUID id,String facultyId,String code,String name,Instant createdAt,Instant updatedAt){public static SubjectView from(Subject s){return new SubjectView(s.id(),s.facultyId(),s.code(),s.name(),s.createdAt(),s.updatedAt());}} public record ChapterView(UUID id,UUID subjectId,String code,String name,int ordinal,Instant createdAt,Instant updatedAt){public static ChapterView from(Chapter c){return new ChapterView(c.id(),c.subjectId(),c.code(),c.name(),c.ordinal(),c.createdAt(),c.updatedAt());}} public record TopicView(UUID id,UUID chapterId,String code,String name,Instant createdAt,Instant updatedAt){public static TopicView from(Topic t){return new TopicView(t.id(),t.chapterId(),t.code(),t.name(),t.createdAt(),t.updatedAt());}}}
